    double weight_sum = 0.0;
    double weighted_sq_sum = 0.0;

    if ((body_vectors == NULL) || (predicted_body_vectors == NULL) || (weights == NULL) ||
        (rms_rad == NULL)) {
        if (rms_rad != NULL) {
            *rms_rad = 0.0;
        }
        return ADCS_E_NULL;
    }

    *rms_rad = 0.0;

    if ((count < 1U) || (count > 32U)) {
        return ADCS_E_RANGE;
    }

    for (k = 0U; k < count; ++k) {
        adcs_vec3_t b_norm;
        adcs_vec3_t p_norm;
        double dot_bp;
        double theta;
        double w;

        if ((!adcs_is_finite_vec3(&body_vectors[k])) ||
            (!adcs_is_finite_vec3(&predicted_body_vectors[k])) || (!isfinite(weights[k])) ||
            (weights[k] <= 0.0)) {
            *rms_rad = 0.0;
            return ADCS_E_RANGE;
        }

        if ((adcs_vec3_normalize(&body_vectors[k], ADCS_EPS_NORM, &b_norm) != ADCS_OK) ||
            (adcs_vec3_normalize(&predicted_body_vectors[k], ADCS_EPS_NORM, &p_norm) != ADCS_OK)) {
            *rms_rad = 0.0;
            return ADCS_E_RANGE;
        }

        dot_bp = adcs_vec3_dot(&b_norm, &p_norm);
        dot_bp = ADCS_CLAMP(dot_bp, -1.0, 1.0);

        theta = acos(dot_bp);
        w = weights[k];

        weighted_sq_sum += w * theta * theta;
        weight_sum += w;
    }

    if (weight_sum <= 0.0) {
        *rms_rad = 0.0;
        return ADCS_E_RANGE;
    }

    *rms_rad = sqrt(weighted_sq_sum / weight_sum);
    return ADCS_OK;
}

